export async function getLeads(): Promise<Lead[]> {
  const mode = await detectMode();
  if (mode === 'api') {
    return apiGet<Lead[]>('/api/leads');
  }
  seedLocalStorage();
  return loadFromStorage<Lead>('leads');
}

